import math

p, b = 0.55, 8000 / 6000
q = 1 - p

def g(f):
    return p * math.log(1 + b * f) + q * math.log(1 - f)

best_f, best_g = 0, g(0)
f = 0.0001
while f < 0.999:
    val = g(f)
    if val > best_g:
        best_f, best_g = f, val
    f += 0.0001

print(round(best_f, 4))   # 0.2125, matching f* = (pb - q) / b
